// The recompute is a PLATFORM-WIDE sweep by design: recompute_inventory_derived()
// takes no tenant argument and refreshes every dealership's inventory in one
// statement. That is the right shape for the WRITE -- it only recomputes derived
// columns on rows that already carry their own owner, so it cannot move a row
// between dealerships and it does not need a tenant to be safe.
//
// The AUDIT ROW is the part that has a tenant. A single row saying 'recomputed
// N units' where N spans every dealership would show Tenant A a number that
// includes somebody else's cars. So this cron ITERATES TENANTS rather than
// resolving one: one audit row per dealership, each quoting only its own count.
const rows = $input.all().map(i => i.json || {});
const counts = {};
for (const r of rows) {
  const t = r.tenant_id;
  if (!t) continue;
  counts[t] = (counts[t] || 0) + 1;
}
const keys = Object.keys(counts);

if (!keys.length) {
  // Either the read-back failed (it fails soft) or nothing is ageing-eligible.
  // Emit ONE row that claims no owner rather than guessing one, and say so.
  return [{ json: { tenant_id: null, units: null } }];
}

return keys.map(t => ({ json: { tenant_id: t, units: counts[t] } }));
